import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
D="تعليمات اتحاد طلبة جامعة العلوم والتكنولوجيا الأردنية"
save("0184",D,[
("rule",[1],"المادة 2 (الهيئة العامة)","الهيئة العامة لاتحاد الطلبة هي جميع الطلبة المنتظمين والمسجلين لنيل درجة البكالوريوس في الجامعة، باستثناء طلبة البرامج الخاصة والطلبة العرب والأجانب وذوي الإعاقة.",
 "من هم أعضاء الهيئة العامة لاتحاد طلبة الجامعة؟","هل طلبة الدراسات العليا والطلبة العرب والأجانب جزء من الهيئة العامة لاتحاد الطلبة؟","مين بكون عضو بالاتحاد؟"),
("number",[1],"المادة 2 (موازنة الاتحاد)","موازنة الاتحاد مخصصات مالية تقرها الجامعة بحسب ما تراه مناسباً، على ألا تزيد عن ثلاثين ألف دينار أردني في الدورة.",
 "ما الحد الأقصى لموازنة اتحاد الطلبة في الدورة؟","كم تبلغ موازنة اتحاد الطلبة؟","قديش موازنة اتحاد الطلبة؟"),
("rule",[2],"المادة 3","اتحاد الطلبة تنظيم طالبي يستمد وجوده من إرادة الطلبة عن طريق الانتخابات الحرة المباشرة أو التعيين، وله شخصية اعتبارية ومخصصات مالية تقرها الجامعة، ومقره داخل الحرم الجامعي في عمادة شؤون الطلبة، ويمارس مهامه من خلال مجلس الاتحاد والهيئة الإدارية ولجان الكليات والأقسام ولجان النشاط.",
 "ما اتحاد الطلبة وأين مقره وما الهيئات التي يمارس من خلالها مهامه؟","ما الهيئات التي يتكون منها اتحاد الطلبة؟","شو هو اتحاد الطلبة ووين مقره؟"),
("rule",[3],"المادة 5","تناط عملية الانتخابات باللجنة العليا للانتخابات التي يرأسها العميد وتتألف من ثلاثة ممثلين عن الاتحاد تسميهم الهيئة الإدارية بشرط عدم ترشحهم، وثلاثة ممثلين عن عمادة شؤون الطلبة من بينهم رئيس اللجنة ومدير دائرة الأنشطة والمبادرات الطلابية كأمين للسر. وتكون اجتماعاتها قانونية بحضور 50% أو أكثر من أعضائها، وفي حال تساوي الأصوات يرجح صوت رئيس اللجنة.",
 "مما تتكون اللجنة العليا لانتخابات اتحاد الطلبة؟","من يرأس اللجنة العليا لانتخابات الاتحاد وما نصاب اجتماعها؟","مين بكون باللجنة العليا لانتخابات الاتحاد؟"),
("rule",[4],"المادة 7 و8","يُعد كل طالب مسجل في الجامعة لنيل درجة البكالوريوس عضواً عاملاً في الاتحاد ما لم يكن مسجلاً في برنامج خاص أو من الطلبة العرب والأجانب وذوي الإعاقة، وتزول عضوية العضو العامل في حالة الانتقال من الجامعة أو التخرج أو الفصل. ويحق للعضو العامل الترشح والتصويت والمشاركة في نشاطات الاتحاد كافة.",
 "من يعتبر عضواً عاملاً في اتحاد الطلبة ومتى تزول عضويته؟","ما حقوق العضو العامل في الاتحاد؟","شو الحقوق اللي عندي كعضو عامل بالاتحاد؟"),
("number",[4],"المادة 10 (1 و2)","يُشترط للترشح لانتخابات مجلس الاتحاد ألا يقل المعدل التراكمي عن (2.0) لطلبة البكالوريوس و(3.0) لطلبة الدراسات العليا، وأن يكون الطالب منتظماً في دراسته عند تقديمه طلب الترشيح وطيلة فترة عضويته في مجلس الاتحاد، ويكون الانتظام بتسجيل الحد الأدنى من الساعات المعتمدة باستثناء الفصل الصيفي.",
 "ما أدنى معدل تراكمي للترشح لانتخابات مجلس اتحاد الطلبة لطالب البكالوريوس؟","ما شرط المعدل التراكمي للترشح لمجلس الاتحاد لطلبة الدراسات العليا؟","كم لازم يكون معدلي عشان أترشح لاتحاد الطلبة؟"),
("number",[4],"المادة 10 (3)","يُشترط للترشح لمجلس الاتحاد أن يكون قد مضى على التحاق الطالب بالجامعة فصلان دراسيان متواصلان على الأقل، وأن يكون قد بقي على تخرجه (36) ساعة دراسية معتمدة بالحد الأدنى. ولطلبة الدراسات العليا يُشترط مضي فصل دراسي وبقاء فصل دراسي على تخرجه بما لا يقل عن (6) ساعات.",
 "كم ساعة يجب أن تتبقى على تخرج طالب البكالوريوس ليترشح لمجلس الاتحاد؟","كم فصلاً يجب أن يمضي على التحاق الطالب ليحق له الترشح لمجلس الاتحاد؟","كم ساعة لازم تضلّ علي للتخرج عشان أترشح للاتحاد؟"),
("rule",[4],"المادة 10 (5 و6 و7)","يُشترط ألا يكون قد صدر بحق المترشح أية عقوبة تأديبية من درجة إنذار أول في السنة التي تسبق الترشيح، ولا أية عقوبة من درجة إنذار ثاني فما فوق، وألا يكون قد ارتكب أية مخالفة تخل بالشرف والسمعة وأدين بها من القضاء.",
 "هل تمنع العقوبات التأديبية من الترشح لمجلس اتحاد الطلبة؟","ما شروط السجل التأديبي للمترشح لانتخابات الاتحاد؟","اذا عليّ عقوبة تأديبية بقدر أترشح للاتحاد؟"),
("number",[4],"المادة 10 (8)","يُشترط أن يكون الطالب المترشح قد بلغ تسعة عشر عاماً ولا يزيد عمره عن ثمانية وعشرين عاماً عند إغلاق باب الترشيح.",
 "ما الحد الأدنى والأقصى لعمر المترشح لانتخابات مجلس اتحاد الطلبة؟","كم عمر الطالب المسموح للترشح لمجلس الاتحاد؟","كم لازم يكون عمري عشان أترشح للاتحاد؟"),
("number",[4],"المادة 10 (9)","على الطالب المترشح في القائمة المحلية (الكليات والأقسام) دفع مبلغ نقدي قدره (50) ديناراً أردنياً كتأمين مسترد، وعلى المترشح عن القائمة العامة (الجامعة) دفع (100) دينار أردني كتأمين مسترد، وفي حال مخالفة المرشح أياً من تعليمات وشروط الترشيح والانتخابات يحق للجنة العليا مصادرة مبلغ التأمين.",
 "كم مبلغ التأمين المطلوب للترشح لانتخابات اتحاد الطلبة؟","ما مبلغ التأمين للقائمة المحلية والقائمة العامة؟","كم لازم أدفع تأمين عشان أترشح بالاتحاد؟"),
("procedure",[4],"المادة 10 (10)","على كل طالب يرغب بترشيح نفسه لانتخابات مجلس اتحاد الطلبة إحضار: هوية جامعية واضحة المعالم أو هوية الأحوال المدنية مع وثيقة إثبات طالب من وحدة القبول والتسجيل، ووصل مالي بقيمة مبلغ التأمين، وشهادة عدم محكومية من قصر العدل.",
 "ما الوثائق المطلوبة للترشح لانتخابات مجلس اتحاد الطلبة؟","هل أحتاج شهادة عدم محكومية للترشح لاتحاد الطلبة؟","شو الأوراق اللي بدي اياها للترشح للاتحاد؟"),
("rule",[5],"المادة 11","تتم عملية الاقتراع لانتخاب مجلس الاتحاد في الفصل الدراسي الثاني من كل عام وتعلن اللجنة العليا المواعيد المحددة لذلك. ويغلق المقر الرئيسي للاتحاد والمقار الفرعية طيلة فترة الإعداد للانتخابات ولمدة (21) يوماً من الموعد الذي تحدده اللجنة العليا تحقيقاً لمبدأ العدالة بين الطلبة.",
 "في أي فصل تجري انتخابات مجلس اتحاد الطلبة؟","لماذا وكم مدة إغلاق مقار الاتحاد قبل الانتخابات؟","متى بصير انتخابات الاتحاد وكم يوم بسكروا مقر الاتحاد قبلها؟"),
("number",[6],"المادة 12 (ب)","يخصص لكل كلية عدد من الأعضاء يتناسب مع أعضاء الهيئة العامة فيها بحيث تكون نسبة التمثيل ممثلاً واحداً لكل (2000) طالب وفق قاعدة التقريب إلى (1000) طالب.",
 "ما نسبة التمثيل في مجلس الاتحاد لكل كلية؟","كم طالباً يمثلهم عضو واحد في مجلس اتحاد الطلبة؟","كل كم طالب بنتخب ممثل بالكلية؟"),
("number",[7],"المادة 13","تتضمن القائمة المحلية عدداً من المترشحين لا يزيد على عدد المقاعد المخصصة للدائرة ولا يقل عن مرشحين اثنين، وينتخب الفائزون في الكلية من بينهم رئيساً للجنة الكلية، وتجري الانتخابات داخل الحرم الجامعي بالاقتراع السري المباشر (ورقياً أو إلكترونياً) ليوم واحد تبدأ فيه عملية الاقتراع مع بداية الدوام وتنتهي بانتهاء الدوام الرسمي.",
 "كم يوماً تستمر عملية الاقتراع في انتخابات الاتحاد؟","ما أدنى عدد من المترشحين في القائمة المحلية؟","كم يوم بتكون الانتخابات وكيف بتصير؟"),
("number",[7],"المادة 14","يتم فتح باب الترشح بقرار من اللجنة العليا خلال الفصل الدراسي الثاني ولمدة ثلاثة أيام دراسية فقط، ولا يجوز التوكيل في الترشيح، وتعلن أسماء المرشحين قبل خمسة أيام دراسية من موعد الانتخابات، وتبدأ الدعاية الانتخابية بعد إعلان الأسماء. ولا يجوز للمرشح المنسحب أثناء فترة الترشح إعادة ترشيحه.",
 "كم مدة فتح باب الترشح لانتخابات اتحاد الطلبة؟","قبل كم يوم تعلن أسماء المرشحين؟ وهل يجوز التوكيل في الترشيح؟","كم يوم بضل باب الترشح مفتوح؟"),
("rule",[7],"المادة 14 (و) و18","يحق للناخب الإدلاء بصوته في دائرته الانتخابية فقط ولمرة واحدة في الانتخاب الواحد ولا يجوز التوكيل في الانتخاب. ويكون الانتخاب باستعمال هوية جامعية واضحة المعالم أو هوية الأحوال المدنية أو رخصة القيادة أو جواز السفر مرفقة بإثبات طالب من وحدة القبول والتسجيل، ولا يجوز اعتماد أي طريقة أخرى.",
 "ما الوثائق المقبولة للتصويت في انتخابات الاتحاد؟","هل يجوز لطالب أن يوكّل غيره بالتصويت؟","شو بحتاج عشان أنتخب بالاتحاد؟"),
("number",[8],"المادة 15 (د) و16","تصدر اللجنة العليا قرارها بقبول طلب الترشح أو رفضه خلال ثلاثة أيام من اليوم التالي لانتهاء تقديم الطلبات. ويجوز لأي مترشح سحب ترشيحه بطلب خطي إلى رئيس اللجنة العليا قبل يوم واحد من يوم الانتخابات، ولا يجوز لأي مترشح ضمن القائمة العامة أن يسحب طلب ترشحه.",
 "هل يمكن سحب الترشح لانتخابات الاتحاد؟ ومتى؟","خلال كم يوم تبت اللجنة العليا بطلبات الترشح؟","بقدر أسحب ترشيحي من الاتحاد؟"),
("rule",[9],"المادة 17","إذا كان عدد المترشحين في القائمة الانتخابية مساوياً لعدد المقاعد المخصصة لتلك الدائرة يقرر رئيس اللجنة العليا فوزهم بالتزكية عند إعلان النتائج النهائية.",
 "متى يفوز المترشحون بالتزكية في انتخابات الاتحاد؟","ماذا يحدث إذا تساوى عدد المترشحين مع عدد المقاعد؟","شو يعني فوز بالتزكية بانتخابات الاتحاد؟"),
("number",[10],"المادة 21 و22","تُحسب نسبة الحسم (العتبة) للقوائم المحلية بنسبة (15%) من مجموع المقترعين في الكلية أو القسم، وللقائمة العامة (5%) من مجموع المقترعين في الدائرة العامة. وإذا تعذر ملء المقاعد بسبب عدم وصول القوائم إلى العتبة تقوم اللجنة العليا بتخفيض العتبة بمقدار (1%) في كل مرة.",
 "ما نسبة الحسم (العتبة) للقوائم المحلية والقائمة العامة في انتخابات الاتحاد؟","ماذا يحدث إذا لم تصل القوائم إلى نسبة الحسم؟","كم نسبة الحسم بانتخابات الاتحاد؟"),
("number",[11],"المادة 24","يحق لأي مرشح أو مفوض قائمة تقديم الطعن في نتائج الانتخابات في دائرته الانتخابية لرئيس اللجنة العليا للانتخابات في مدة لا تتجاوز ثلاثة أيام دراسية من تاريخ انتخاب الهيئة الإدارية الجديدة، وقرار اللجنة نهائي وملزم وغير قابل للطعن مرة أخرى.",
 "خلال كم يوماً يمكن الطعن في نتائج انتخابات اتحاد الطلبة؟","هل قرار اللجنة العليا في الطعن نهائي؟","كم يوم عندي أطعن بنتيجة الانتخابات؟"),
("number",[11],"المادة 25","مجلس الاتحاد هو أعلى سلطة للاتحاد وقراراته ملزمة لكل هيئات الاتحاد، ومدة عضويته عامان تجري بعدها انتخابات جديدة. ويتولى انتخاب الهيئة الإدارية بالاقتراع السري المباشر، ورسم السياسة العامة للاتحاد والمصادقة على خطة عمله وموازنته.",
 "ما مدة عضوية مجلس اتحاد الطلبة؟","ما أعلى سلطة في اتحاد الطلبة وما صلاحياتها؟","كم سنة مدة مجلس الاتحاد؟"),
("number",[12],"المادة 26 (أ و ب)","يجتمع مجلس الاتحاد اجتماعاً عادياً في بداية كل فصل واجتماعاً في نهاية مدته، ويجوز دعوته لاجتماع استثنائي بموافقة عمادة شؤون الطلبة بدعوة من الهيئة الإدارية أو بطلب خطي من ثلث أعضاء المجلس على الأقل، وعندها يجب على الهيئة الإدارية دعوة المجلس خلال أسبوع من تقديم الطلب.",
 "متى يجتمع مجلس اتحاد الطلبة اجتماعاً عادياً؟","من يستطيع طلب اجتماع استثنائي لمجلس الاتحاد؟","كل قديش بجتمع مجلس الاتحاد؟"),
("number",[12],"المادة 26 (و و ز)","يُفصل عضو المجلس في حالة غيابه ثلاث مرات متتالية أو ست مرات متفرقة عن اجتماعات المجلس دون عذر يقبله المجلس، وإذا قل عدد أعضاء مجلس الاتحاد عن النصف يُحل المجلس وتُجرى انتخابات جديدة مباشرة.",
 "كم مرة يمكن لعضو مجلس الاتحاد أن يتغيب قبل فصله؟","متى يُحل مجلس اتحاد الطلبة؟","كم مرة بقدر أغيب عن اجتماعات مجلس الاتحاد؟"),
("rule",[12],"المادة 26 (ح و ط)","يُنتخب رئيس الاتحاد من قبل أعضاء مجلس الاتحاد بشرط أن يكون أردني الجنسية. وإذا لم يحصل المرشحون على الأغلبية المطلقة من أصوات الأعضاء الحاضرين تجرى جولة ثانية بين المرشحين الحاصلين على أعلى الأصوات، وإن لم تحسم النتيجة تُجرى القرعة.",
 "كيف يُنتخب رئيس اتحاد الطلبة وما شرط جنسيته؟","ماذا يحدث إذا لم يحصل مرشح رئاسة الاتحاد على الأغلبية المطلقة؟","كيف بنختار رئيس الاتحاد؟"),
],"a",verified="text")
